export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  if (slug === 'implant-specialist-in-panvel') {
    return blogPosts.find(post => post.slug === 'dental-implantologist-in-panvel-complete-guide');
  }
  if (slug === 'invisalign-in-panvel') {
    return blogPosts.find(post => post.slug === 'invisalign-in-panvel-complete-guide');
  }
  return blogPosts.find(post => post.slug === slug);
}

export function getAllBlogSlugs(): string[] {
  const slugs = blogPosts.map(post => post.slug);
  if (!slugs.includes('implant-specialist-in-panvel')) {
    slugs.push('implant-specialist-in-panvel');
  }
  if (!slugs.includes('invisalign-in-panvel')) {
    slugs.push('invisalign-in-panvel');
  }
  return slugs;
}

export function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
}
